// 构建条目与别名索引
const ENTRIES = CITIES.map(([name, nameZh, country, countryZh, lat, lng]) => ({
  name,
  nameZh,
  country,
  countryZh,
  lat,
  lng,
}));

const ALIAS = new Map(); // 小写英文/中文 -> entry
for (const e of ENTRIES) {
  ALIAS.set(e.name.toLowerCase(), e);
  ALIAS.set(e.nameZh, e);
}

/** 精确查找（英文名或中文名） */
export function lookupCity(query) {
  if (!query) return null;
  const q = query.trim();
  return ALIAS.get(q.toLowerCase()) || ALIAS.get(q) || null;
}

/** 搜索：前缀优先 + 包含匹配，返回最多 limit 个结果 */
export function searchCities(query, limit = 6) {
  const q = (query || '').trim().toLowerCase();
  if (!q) return [];
  const starts = [];
  const contains = [];
  for (const e of ENTRIES) {
    if (e.name.toLowerCase().startsWith(q) || e.nameZh.startsWith(q)) {
      starts.push(e);
    } else if (e.name.toLowerCase().includes(q) || e.nameZh.includes(q)) {
      contains.push(e);
    }
  }
  return [...starts, ...contains].slice(0, limit);
}

// views/journeyForm.js — 视图④：Add / Edit Journey 表单（起点 / 终点）
import { ViewBase } from './viewBase.js';
import { icon, el, clear } from '../utils/dom.js';
import { lookupCity, searchCities } from '../utils/cityIndex.js';
import { uuid } from '../utils/id.js';

const QUICK_CITIES = {
  start: ['北京', '上海', '广州', '深圳', '东京', '大阪', '香港'],
  destination: ['北京', '上海', '广州', '深圳', '东京', '大阪', '香港'],
};

export class JourneyForm extends ViewBase {
  render() {
    this.root = el('div', {});
    this.head = el('div', { class: 'page-head page-head-row' });
    const back = el('button', { class: 'icon-btn', onclick: () => this.app.router.back() }, [icon('back', 16)]);
    this.titleEl = el('div', { class: 'display' }, '');
    this.head.appendChild(back);
    this.head.appendChild(this.titleEl);
    this.head.appendChild(el('div', { style: { width: 38 } }));

    this.scroll = el('div', { class: 'view-scroll form-wrap' });
    this.root.appendChild(this.head);
    this.root.appendChild(this.scroll);

    return this.root;
  }

  onMount() {
    const params = this.app.router.current?.params || {};
    this._editingId = params.id || null;
    this._start = this._blankDraft();
    this._destination = this._blankDraft();
    if (!this._editingId) {
      const now = new Date();
      const today = [now.getFullYear(), String(now.getMonth() + 1).padStart(2, '0'), String(now.getDate()).padStart(2, '0')].join('-');
      this._start.arriveAt = this._destination.arriveAt = today;
    }
    this._build();
  }

  _build() {
    const repo = this.app.repo;
    clear(this.scroll);

    const editing = !!this._editingId;
    this.titleEl.textContent = this.t(editing ? 'form.edit' : 'form.new');

    let existing = null;
    if (editing) {
      existing = repo.state.journeys.find((j) => j.id === this._editingId);
      if (!existing) {
        this.app.router.go('journeys');
        return;
      }
    }

    // 旅程字段
    this.nameInput = el('input', { class: 'input', placeholder: this.t('form.namePh') });
    this.nameInput.value = existing ? existing.title : '';

    this.scroll.appendChild(
      el('div', { class: 'field' }, [el('label', { text: this.t('form.name') }), this.nameInput])
    );

    // 起点
    this.scroll.appendChild(this._sectionLabel('form.start'));
    this.startWrap = el('div', { class: 'place-editor' });
    this.scroll.appendChild(this.startWrap);

    // 终点
    this.scroll.appendChild(this._sectionLabel('form.destination'));
    this.destWrap = el('div', { class: 'place-editor' });
    this.scroll.appendChild(this.destWrap);

    // 初始化地点
    if (existing) {
      const list = repo.placesByJourney(existing.id);
      const start = list.find((p) => p.role === 'start') || list[0];
      const dest = list.find((p) => p.role === 'destination') || list[list.length - 1];
      this._start = start ? this._toDraft(start) : this._blankDraft();
      this._destination = dest && dest !== start ? this._toDraft(dest) : this._blankDraft();
      if (!this._start.arriveAt) this._start.arriveAt = existing.startDate || '';
      if (!this._destination.arriveAt) this._destination.arriveAt = existing.endDate || '';
    }
    this._renderSections();

    // 操作按钮
    const actions = el('div', { style: { display: 'flex', gap: '10px', marginTop: '24px' } });
    const saveBtn = el('button', { class: 'btn btn-primary', style: { flex: 1 }, onclick: () => this._save() }, [el('span', { text: this.t('form.save') })]);
    actions.appendChild(saveBtn);
    if (editing) {
      const delBtn = el('button', { class: 'btn btn-danger', onclick: () => this._delete() }, [icon('trash', 15)]);
      actions.appendChild(delBtn);
    }
    this.scroll.appendChild(actions);

    this.app.i18n.applyI18n(this.root);
  }

  _sectionLabel(key) {
    return el('div', { class: 'form-section' }, [
      el('span', { class: 'form-section-title', 'data-i18n': key }),
    ]);
  }

  _toDraft(p) {
    return {
      id: p.id,
      name: p.name,
      country: p.country || '',
      lat: p.lat != null ? String(p.lat) : '',
      lng: p.lng != null ? String(p.lng) : '',
      arriveAt: (p.arriveAt || '').slice(0, 10),
      note: p.note || '',
      photoIds: p.photoIds || [],
      _photos: [],
      _photoUrls: [],
    };
  }

  _blankDraft() {
    return {
      id: null,
      name: '',
      country: '',
      lat: '',
      lng: '',
      arriveAt: '',
      note: '',
      photoIds: [],
      _photos: [],
      _photoUrls: [],
    };
  }

  _renderSections() {
    // 起点
    clear(this.startWrap);
    this.startWrap.appendChild(this._placeCard(this._start, 'start'));

    // 终点
    clear(this.destWrap);
    this.destWrap.appendChild(this._placeCard(this._destination, 'destination'));
  }

  _placeCard(p, role) {
    const card = el('div', { class: 'place-card', 'data-role': role });

    // 名称（含城市搜索）+ 操作按钮
    const nameRow = el('div', { class: 'place-card-head' });
    nameRow.appendChild(this._nameField(p));
    card.appendChild(nameRow);

    const quick = el('div', { class: 'quick-cities' });
    quick.appendChild(el('span', { class: 'quick-cities-label', text: this.t('form.commonCities') }));
    const chips = el('div', { class: 'quick-cities-scroll' });
    for (const city of QUICK_CITIES[role]) {
      const hit = lookupCity(city);
      chips.appendChild(el('button', { class: 'city-chip', type: 'button', onclick: () => this._selectCity(p, hit) }, hit.nameZh));
    }
    quick.appendChild(chips);
    card.appendChild(quick);

    // 日期 + 坐标
    const row2 = el('div', { class: 'place-card-row' });
    const dateLabel = role === 'start' ? 'form.startDate' : 'form.endDate';
    const dateField = el('label', { class: 'place-date-field' }, [el('span', { text: this.t(dateLabel) })]);
    const dateInput = el('input', { class: 'input', type: 'date' });
    dateInput.value = p.arriveAt;
    dateInput.addEventListener('input', () => (p.arriveAt = dateInput.value));
    dateField.appendChild(dateInput);
    row2.appendChild(dateField);

    const latInput = el('input', { class: 'input', type: 'number', step: 'any', placeholder: this.t('form.lat') });
    latInput.value = p.lat;
    latInput.addEventListener('input', () => (p.lat = latInput.value));
    const lngInput = el('input', { class: 'input', type: 'number', step: 'any', placeholder: this.t('form.lng') });
    lngInput.value = p.lng;
    lngInput.addEventListener('input', () => (p.lng = lngInput.value));
    row2.appendChild(latInput);
    row2.appendChild(lngInput);
    card.appendChild(row2);

    // 备注
    const noteInput = el('input', { class: 'input', placeholder: this.t('form.note') });
    noteInput.value = p.note;
    noteInput.addEventListener('input', () => (p.note = noteInput.value));
    card.appendChild(noteInput);

    // 照片
    const photoRow = el('div', { class: 'place-photos' });
    const addPhoto = el('button', { class: 'mini-btn', title: this.t('form.photos'), onclick: () => this._pickPhoto(p) }, [icon('image', 15)]);
    photoRow.appendChild(addPhoto);
    const thumbs = el('div', { class: 'thumbs' });
    for (const id of p.photoIds) thumbs.appendChild(this._thumbImg(id, null));
    for (const url of p._photoUrls) thumbs.appendChild(this._thumbImg(null, url));
    photoRow.appendChild(thumbs);
    card.appendChild(photoRow);

    return card;
  }

  _thumbImg(id, url) {
    const img = el('img', { class: 'thumb' });
    if (url) img.src = url;
    else if (id) {
      this.app.repo.getPhotoUrl(id).then((u) => {
        if (u) img.src = u;
      });
    }
    return img;
  }

  _autofill(p, input) {
    const hit = lookupCity(input.value);
    if (hit) {
      this._applyCity(p, hit);
      input.value = hit.name;
      const card = input.closest('.place-card');
      const numbers = card.querySelectorAll('input[type="number"]');
      numbers[0].value = p.lat;
      numbers[1].value = p.lng;
    }
  }

  _applyCity(p, hit) {
    p.name = hit.name;
    p.country = hit.country;
    p.lat = String(hit.lat);
    p.lng = String(hit.lng);
  }

  _selectCity(p, hit) {
    this._applyCity(p, hit);
    this._renderSections();
  }

  /** 城市名称输入框（含自动补全下拉） */
  _nameField(p) {
    const wrap = el('div', { class: 'city-search' });
    const input = el('input', { class: 'input', placeholder: this.t('form.placeNamePh') });
    input.value = p.name;
    const suggest = el('div', { class: 'city-suggest' });
    suggest.style.display = 'none';

    input.addEventListener('input', () => {
      p.name = input.value;
      p.country = '';
      p.lat = '';
      p.lng = '';
      this._showSuggestions(suggest, input, p);
    });
    input.addEventListener('focus', () => this._showSuggestions(suggest, input, p));
    input.addEventListener('blur', () => {
      setTimeout(() => (suggest.style.display = 'none'), 160);
      this._autofill(p, input);
    });

    wrap.appendChild(input);
    wrap.appendChild(suggest);
    return wrap;
  }

  _showSuggestions(suggest, input, p) {
    const q = input.value.trim();
    clear(suggest);
    if (!q || (p.lat && p.lng)) {
      suggest.style.display = 'none';
      return;
    }
    const matches = searchCities(q, 6);
    if (!matches.length) {
      suggest.style.display = 'none';
      return;
    }
    for (const m of matches) {
      const item = el('div', { class: 'city-suggest-item', onmousedown: (e) => e.preventDefault() });
      item.appendChild(
        el('span', { class: 'n' }, m.nameZh && m.nameZh !== m.name ? `${m.nameZh} · ${m.name}` : m.name)
      );
      item.appendChild(el('span', { class: 'c' }, m.countryZh || m.country));
      item.addEventListener('click', () => {
        this._selectCity(p, m);
      });
      suggest.appendChild(item);
    }
    suggest.style.display = 'block';
  }

  _pickPhoto(p) {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.multiple = true;
    input.onchange = () => {
      for (const file of input.files) {
        p._photos.push(file);
        p._photoUrls.push(URL.createObjectURL(file));
      }
      this._renderSections();
    };
    input.click();
  }

  _toRow(p, role) {
    return {
      id: p.id || uuid(),
      name: p.name.trim(),
      country: p.country || '',
      city: p.name.trim(),
      lat: p.lat === '' ? null : parseFloat(p.lat),
      lng: p.lng === '' ? null : parseFloat(p.lng),
      arriveAt: p.arriveAt ? `${p.arriveAt}T00:00` : null,
      departAt: null,
      note: p.note || '',
      photoIds: p.photoIds || [],
      role,
    };
  }

  // Save always takes a fresh snapshot from the rendered cards. This keeps DOM edits,
  // quick-city selections, and the in-memory drafts on the same path.
  _snapshotPlaces() {
    const rows = [];
    for (const card of this.scroll.querySelectorAll('.place-card')) {
      const role = card.dataset.role;
      const draft = role === 'start' ? this._start : role === 'destination' ? this._destination : null;
      if (!draft) continue;
      const nameInput = card.querySelector('.city-search input');
      const dateInput = card.querySelector('input[type="date"]');
      const numbers = card.querySelectorAll('input[type="number"]');
      const name = nameInput?.value.trim() || '';
      const hit = lookupCity(name);
      draft.name = name;
      draft.arriveAt = dateInput?.value || '';
      draft.lat = numbers[0]?.value || '';
      draft.lng = numbers[1]?.value || '';
      if (hit) {
        draft.country = hit.country;
        // A changed city must replace the previous chip coordinates.
        draft.lat = String(hit.lat);
        draft.lng = String(hit.lng);
      }
      rows.push({ draft, role });
    }
    return rows;
  }

  async _save() {
    const repo = this.app.repo;
    const name = this.nameInput.value.trim();
    const snapshots = this._snapshotPlaces();
    const start = snapshots.find((x) => x.role === 'start')?.draft;
    const dest = snapshots.find((x) => x.role === 'destination')?.draft;
    if (!name) {
      this.app.toast(this.t('form.needName'));
      this.nameInput.focus();
      return;
    }
    if (!start?.name || !dest?.name) {
      this.app.toast(this.t('form.needStartDest'));
      return;
    }
    const ordered = snapshots.map((x) => x.draft);
    const drafts = ordered;
    if (drafts.some((p) => !p.name || !Number.isFinite(Number(p.lat)) || !Number.isFinite(Number(p.lng)) || p.lat === '' || p.lng === '')) {
      this.app.toast(this.t('form.needCoordinates'));
      return;
    }
    if (!start.arriveAt || !dest.arriveAt || dest.arriveAt < start.arriveAt) {
      this.app.toast(this.t('form.needDates'));
      return;
    }

    const placeRows = snapshots.map((x) => this._toRow(x.draft, x.role));
    const savedStart = placeRows.find((p) => p.role === 'start');
    const savedDestination = placeRows.find((p) => p.role === 'destination');
    if (!savedStart || !savedDestination) {
      this.app.toast(this.t('form.needStartDest'));
      return;
    }

    console.info('[JourneyForm] save input', { journeyId: this._editingId, title: name, placeRows });

    const journey = {
      id: this._editingId || uuid(),
      title: name,
      subtitle: '',
      startDate: start.arriveAt,
      endDate: dest.arriveAt,
      description: '',
      coverColor: '#e09b57',
    };

    await repo.saveJourney(journey);
    console.info('[JourneyForm] journey write input', journey);

    await repo.savePlaces(journey.id, placeRows);
    const persisted = await repo.debugJourneySave(journey.id);
    console.info('[JourneyForm] persisted comparison', {
      journeyMatches: JSON.stringify({ ...journey, createdAt: persisted.journey?.createdAt, updatedAt: persisted.journey?.updatedAt }) === JSON.stringify(persisted.journey),
      placeRows,
      persistedPlaces: persisted.places,
    });

    // 上传新照片（按顺序映射到已保存的地点）
    const savedPlaces = repo.placesByJourney(journey.id);
    for (let i = 0; i < drafts.length; i++) {
      const saved = savedPlaces[i];
      if (!saved) continue;
      for (const file of drafts[i]._photos) {
        await repo.savePhoto({
          journeyId: journey.id,
          placeId: saved.id,
          blob: file,
          mime: file.type,
        });
      }
    }

    if (!this._editingId) {
      // 新旅程：回地图 → 定位 → 路线重新生长 → 提示
      this.app.pendingNewJourney = journey.id;
      this.app.router.go('map');
    } else {
      this.app.toast(this.t('toast.saved'));
      this.app.router.go('journeys');
    }
  }

  async _delete() {
    if (!this._editingId) return;
    if (!confirm(this.t('form.deleteConfirm'))) return;
    await this.app.repo.deleteJourney(this._editingId);
    this.app.toast(this.t('toast.deleted'));
    this.app.router.go('journeys');
  }
}

// views/statsView.js — 视图③：Stats（Travel Profile / Archive）
// 区块：核心数据 / 旅行热度 / 洞察 / 精彩瞬间 / 时间线 / 足迹
import { ViewBase } from './viewBase.js';
import { el, clear } from '../utils/dom.js';
import { tween, EASE_OUT } from '../core/tween.js';
import { fmtNumber, yearOf, monthName, fmtShort, fmtDate } from '../utils/date.js';
import { distanceBetween } from '../data/repo.js';
import { buildFootprintMap } from './footprintMap.js';
import { on } from '../core/eventbus.js';

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export class StatsView extends ViewBase {
  render() {
    this.root = el('div', { class: 'stats-page' });
    this.head = el('div', { class: 'page-head' });
    this.head.appendChild(el('div', { class: 'sub', style: { textTransform: 'uppercase', letterSpacing: '0.14em' } }, this.t('stats.title')));
    this.scroll = el('div', { class: 'view-scroll' });
    this.root.appendChild(this.head);
    this.root.appendChild(this.scroll);
    this._unsub = on('data:changed', () => this._render());
    return this.root;
  }

  onMount() {
    this._render();
  }

  onShow() {
    this._render();
  }

  unmount() {
    this._unsub();
    super.unmount();
  }

  _render() {
    const repo = this.app.repo;
    const years = [...new Set(repo.state.journeys.map(j => yearOf(j.startDate)).filter(Boolean))].sort((a, b) => b - a);
    if (!years.includes(this._year)) this._year = null;
    const journeys = repo.state.journeys.filter(j => !this._year || yearOf(j.startDate) === this._year);
    const places = journeys.flatMap(j => repo.placesByJourney(j.id));
    const uniquePlaces = this._year
      ? [...new Map(places.map(p => [`${p.name}|${p.lat}|${p.lng}`, p])).values()]
      : repo.uniquePlaces();
    const s = this._year ? {
      cities: uniquePlaces.length,
      countries: new Set(uniquePlaces.map(p => p.country).filter(Boolean)).size,
      journeys: journeys.length,
      distance: Math.round(journeys.reduce((sum, j) => {
        const route = repo.placesByJourney(j.id);
        return sum + route.slice(1).reduce((km, place, i) => km + distanceBetween(route[i], place), 0);
      }, 0)),
    } : repo.stats();
    const locale = this.app.i18n.getLang();
    clear(this.scroll);
    this.head.firstChild.textContent = this.t('stats.title');
    if (years.length) {
      const select = el('select', {
        class: 'stats-year-select', 'aria-label': this.t('stats.year'),
        onchange: event => { this._year = Number(event.target.value) || null; this._render(); this.scroll.querySelector('select')?.focus(); },
      }, [el('option', { value: '' }, this.t('stats.all')), ...years.map(y => el('option', { value: y }, String(y)))]);
      select.value = this._year || '';
      this.scroll.appendChild(el('div', { class: 'stats-filter' }, [
        el('span', {}, this.t('stats.year')), select,
      ]));
    }

    // ===== 区块 1：核心数据 =====
    const grid = el('div', { class: 'stats-grid' });
    const cards = [
      { num: s.cities, label: this.t('stats.cities') },
      { num: s.countries, label: this.t('stats.countries') },
      { num: s.journeys, label: this.t('stats.journeys') },
      { num: s.distance, label: this.t('stats.distance'), format: true, suffix: ' ' + this.t('common.km') },
    ];
    this._targets = [];
    for (const c of cards) {
      const numEl = el('div', { class: 'num' }, '0');
      const value = el('div', { class: 'stat-value' }, [numEl]);
      if (c.suffix) value.appendChild(el('span', { class: 'stat-unit' }, c.suffix.trim()));
      const card = el('div', { class: 'stat-card' }, [value, el('div', { class: 'label' }, c.label)]);
      grid.appendChild(card);
      this._targets.push({ el: numEl, to: c.num, format: !!c.format, suffix: c.suffix || '', locale });
    }
    this.scroll.appendChild(grid);

    // Count-up
    for (const tg of this._targets) {
      tween({
        from: { v: 0 },
        to: { v: tg.to },
        duration: 900,
        ease: EASE_OUT,
        onUpdate: (o) => {
          const val = Math.round(o.v);
          tg.el.textContent = tg.format ? fmtNumber(val, tg.locale) : String(val);
        },
      });
    }

    const hasData = journeys.length > 0;

    // ===== 区块 2：年度旅行热度 =====
    const heat = this._buildHeat(journeys, repo, locale);
    if (heat) {
      this.scroll.appendChild(this._section('stats.heat'));
      this.scroll.appendChild(heat);
    }

    if (hasData) {
      this.scroll.appendChild(this._section('stats.insights'));
      this.scroll.appendChild(el('div', { class: 'stats-insights' }, this._buildInsights(journeys, repo, locale)));
    }

    // ===== 区块 4：Travel Highlights =====
    const highlights = this._buildHighlights(journeys, repo, locale);
    if (highlights.length) {
      this.scroll.appendChild(this._section('stats.highlights'));
      this.scroll.appendChild(el('div', { class: 'highlights' }, highlights));
    }

    // ===== 区块 5：Travel Timeline =====
    if (hasData) {
      this.scroll.appendChild(this._section('stats.timeline'));
      this.scroll.appendChild(this._buildTimeline(journeys, repo, locale));
    }

    // ===== 区块 6：Travel Footprint（足迹地图） =====
    if (hasData) {
      this.scroll.appendChild(this._section('stats.footprint'));
      const wrap = el('div', { class: 'footprint-wrap' });
      this.scroll.appendChild(wrap);
      // 异步渲染足迹地图（复用底图数据，有缓存）
      const w = wrap.clientWidth || 320;
      buildFootprintMap({
        width: w,
        height: Math.round(w * 0.56),
        places: uniquePlaces,
        journeys,
        placesByJourney: (id) => repo.placesByJourney(id),
      }).then((svg) => {
        if (!wrap.isConnected) return;
        clear(wrap);
        wrap.appendChild(svg);
      });
    }

    // 无数据空状态
    if (!hasData) {
      this.scroll.appendChild(
        el('div', { class: 'empty' }, [
          el('div', { class: 'icon' }, '◌'),
          el('div', { text: this.t('journeys.empty') }),
          el('div', { text: this.t('journeys.emptyHint') }),
        ])
      );
    }
  }

  _section(key) {
    return el('div', { class: 'stats-section' }, [el('span', { text: this.t(key) })]);
  }

  // ---- 时间线：年份 → 月份 → 旅程（A → B → C） ----
  _buildTimeline(journeys, repo, locale) {
    const wrap = el('div', { class: 'stats-timeline' });
    const sorted = [...journeys].sort((a, b) => ((a.startDate || '') < (b.startDate || '') ? 1 : -1));

    let curYear = null;
    let curMonth = null;
    for (const j of sorted) {
      const date = (j.startDate || '').slice(0, 10);
      if (!date) continue;
      const y = yearOf(date);
      const m = monthName(date, locale);
      const monthKey = `${y}-${m}`;
      if (y !== curYear) {
        curYear = y;
        curMonth = null;
        wrap.appendChild(el('div', { class: 'stl-year' }, String(y)));
      }
      if (monthKey !== curMonth) {
        curMonth = monthKey;
        wrap.appendChild(el('div', { class: 'stl-month' }, m));
      }
      const ps = repo.placesByJourney(j.id);
      const routeStr = ps.length ? ps.map((p) => p.name).join(' → ') : j.title;
      const item = el('div', { class: 'stl-item', onclick: () => this._goMap() }, [
        el('span', { class: 'stl-dot' }),
        el('div', { class: 'stl-body' }, [
          el('div', { class: 'stl-route' }, routeStr),
          j.title && j.title !== routeStr ? el('div', { class: 'stl-title' }, j.title) : null,
        ]),
        el('span', { class: 'stl-date' }, fmtShort(date, locale)),
      ]);
      wrap.appendChild(item);
    }
    return wrap;
  }

  _goMap() {
    this.app.router.go('map');
  }

  // ---- Highlights：从真实数据计算 ----
  _buildInsights(journeys, repo, locale) {
    const out = [];

    // 最长旅程（总距离）
    let longest = null;
    let longestKm = 0;
    for (const j of journeys) {
      const ps = repo.placesByJourney(j.id);
      let d = 0;
      for (let i = 1; i < ps.length; i++) d += distanceBetween(ps[i - 1], ps[i]);
      if (d > longestKm) {
        longestKm = d;
        longest = j;
      }
    }
    if (longest && longestKm > 0) {
      out.push(
        this._highlight(
          this.t('stats.highlightLongest'),
          (longest.title || '').trim() || repo.placesByJourney(longest.id).map((p) => p.name).join(' → '),
          this.t('stats.totalDistance') + ' · ' + fmtNumber(Math.round(longestKm), locale) + ' ' + this.t('common.km')
        )
      );
    }

    // 单段最长航段（最远的两城市）
    let farA = null;
    let farB = null;
    let farKm = 0;
    for (const j of journeys) {
      const ps = repo.placesByJourney(j.id);
      for (let i = 1; i < ps.length; i++) {
        const d = distanceBetween(ps[i - 1], ps[i]);
        if (d > farKm) {
          farKm = d;
          farA = ps[i - 1];
          farB = ps[i];
        }
      }
    }
    if (farA && farB && farKm > 0) {
      out.push(
        this._highlight(
          this.t('stats.highlightFarthest'),
          `${farA.name} → ${farB.name}`,
          this.t('stats.longestLeg') + ' · ' + fmtNumber(Math.round(farKm), locale) + ' ' + this.t('common.km')
        )
      );
    }

    const latest = [...journeys].filter(j => yearOf(j.startDate)).sort((a, b) => b.startDate.localeCompare(a.startDate))[0];
    if (latest) out.push(this._highlight(this.t('stats.latest'), latest.title || repo.placesByJourney(latest.id).map(p => p.name).join(' → '), fmtDate(latest.startDate, locale)));
    // 同一次旅程重复经过同一城市只计一次，与现有城市去重口径一致。
    const visits = new Map();
    for (const j of journeys) {
      const cities = new Map(repo.placesByJourney(j.id).map(p => [`${p.name}|${p.lat}|${p.lng}`, p.name]));
      for (const [key, name] of cities) visits.set(key, { name, n: (visits.get(key)?.n || 0) + 1 });
    }
    const top = [...visits.values()].sort((a, b) => b.n - a.n)[0];
    if (top) out.push(this._highlight(this.t('stats.topCity'), top.name, fmtNumber(top.n, locale) + ' ' + this.t('stats.visitJourneys')));
    return out;
  }

  _buildHighlights(journeys, repo, locale) {
    const out = [];
    // 旅行最多的国家
    const countryCount = new Map();
    for (const p of journeys.flatMap(j => repo.placesByJourney(j.id))) {
      if (!p.country) continue;
      countryCount.set(p.country, (countryCount.get(p.country) || 0) + 1);
    }
    let topCountry = null;
    let topCountryN = 0;
    for (const [c, n] of countryCount) {
      if (n > topCountryN) {
        topCountryN = n;
        topCountry = c;
      }
    }
    if (topCountry) {
      out.push(this._highlight(this.t('stats.highlightCountry'), topCountry, fmtNumber(topCountryN, locale) + ' ' + this.t('stats.visits')));
    }

    // 访问城市最多的年份
    const yearPlaces = new Map();
    for (const j of journeys) {
      const y = yearOf(j.startDate);
      if (!y) continue;
      const ps = repo.placesByJourney(j.id);
      yearPlaces.set(y, (yearPlaces.get(y) || 0) + ps.length);
    }
    let topYear = null;
    let topYearN = 0;
    for (const [y, n] of yearPlaces) {
      if (n > topYearN) {
        topYearN = n;
        topYear = y;
      }
    }
    if (topYear) {
      out.push(this._highlight(this.t('stats.highlightYear'), String(topYear), fmtNumber(topYearN, locale) + ' ' + this.t('stats.visits')));
    }

    return out;
  }

  _highlight(label, value, sub) {
    return el('div', { class: 'highlight' }, [
      el('div', { class: 'h-label' }, label),
      el('div', { class: 'h-value' }, value),
      el('div', { class: 'h-sub' }, sub),
    ]);
  }

  // ---- 年度热度：12 个月到访城市数映射强度 ----
  _buildHeat(journeys, repo, locale) {
    const counts = new Array(12).fill(0);
    for (const j of journeys) {
      const ps = repo.placesByJourney(j.id);
      // 用旅程内每个地点的到达时间或旅程开始时间落月
      for (const p of ps) {
        const d = (p.arriveAt || j.startDate || '').slice(0, 10);
        if (!d) continue;
        const m = new Date(d.length === 10 ? d + 'T00:00:00' : d).getMonth();
        if (isNaN(m)) continue;
        counts[m]++;
      }
    }
    if (!journeys.length) return null;

    const max = Math.max(...counts);
    const wrap = el('div', { class: 'heat-grid' });
    for (let m = 0; m < 12; m++) {
      const n = counts[m];
      // 强度 0~4 档
      const level = n > 0 ? Math.max(1, Math.ceil((n / max) * 4)) : 0;
      const month = locale === 'zh' ? `${m + 1}月` : MONTHS[m];
      const description = `${month} · ${n} ${this.t('stats.visits')}`;
      const cell = el('div', { class: 'heat-cell', 'data-level': level, title: description, 'aria-label': description }, [
        el('span', { class: 'heat-month' }, month),
        el('span', { class: 'heat-dot' }),
      ]);
      wrap.appendChild(cell);
    }
    return wrap;
  }
}

// data/db.js — IndexedDB 封装
import { DB_NAME, DB_VERSION, STORES } from '../config.js';

let dbPromise = null;

function open() {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = (e) => {
      const db = e.target.result;
      // settings: key -> value
      if (!db.objectStoreNames.contains('settings')) {
        db.createObjectStore('settings', { keyPath: 'key' });
      }
      // journeys
      if (!db.objectStoreNames.contains('journeys')) {
        const s = db.createObjectStore('journeys', { keyPath: 'id' });
        s.createIndex('startDate', 'startDate');
      }
      // places
      if (!db.objectStoreNames.contains('places')) {
        const s = db.createObjectStore('places', { keyPath: 'id' });
        s.createIndex('journeyId', 'journeyId');
        s.createIndex('journeyId_seq', ['journeyId', 'seq']);
      }
      // photos (metadata only)
      if (!db.objectStoreNames.contains('photos')) {
        const s = db.createObjectStore('photos', { keyPath: 'id' });
        s.createIndex('placeId', 'placeId');
        s.createIndex('journeyId', 'journeyId');
      }
      // blobs
      if (!db.objectStoreNames.contains('blobs')) {
        db.createObjectStore('blobs', { keyPath: 'id' });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  return dbPromise;
}

function tx(db, stores, mode = 'readonly') {
  return db.transaction(stores, mode);
}

function promisify(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export async function getAll(store) {
  const db = await open();
  return promisify(tx(db, store).objectStore(store).getAll());
}

export async function get(store, key) {
  const db = await open();
  return promisify(tx(db, store).objectStore(store).get(key));
}

export async function put(store, value) {
  const db = await open();
  return promisify(tx(db, store, 'readwrite').objectStore(store).put(value));
}

export async function bulkPut(store, values) {
  const db = await open();
  const t = tx(db, store, 'readwrite');
  const os = t.objectStore(store);
  values.forEach((v) => os.put(v));
  return new Promise((resolve, reject) => {
    t.oncomplete = () => resolve();
    t.onerror = () => reject(t.error);
  });
}

export async function del(store, key) {
  const db = await open();
  return promisify(tx(db, store, 'readwrite').objectStore(store).delete(key));
}

export async function bulkDel(store, keys) {
  const db = await open();
  const t = tx(db, store, 'readwrite');
  const os = t.objectStore(store);
  keys.forEach((k) => os.delete(k));
  return new Promise((resolve, reject) => {
    t.oncomplete = () => resolve();
    t.onerror = () => reject(t.error);
  });
}

export async function clear(store) {
  const db = await open();
  return promisify(tx(db, store, 'readwrite').objectStore(store).clear());
}

export async function getAllByIndex(store, index, value) {
  const db = await open();
  return promisify(tx(db, store).objectStore(store).index(index).getAll(value));
}

export default { open, getAll, get, put, bulkPut, del, bulkDel, clear, getAllByIndex };

// data/repo.js — 数据仓库 + 内存 state + 派生选择器
import * as db from './db.js';
import { uuid } from '../utils/id.js';
import { emit, on } from '../core/eventbus.js';

// 内存 state
export const state = {
  settings: {},
  journeys: [],
  places: [],
  photos: [],
  loaded: false,
};

// ---- 设置 ----
export async function loadAll() {
  const [settings, journeys, places, photos] = await Promise.all([
    db.getAll('settings'),
    db.getAll('journeys'),
    db.getAll('places'),
    db.getAll('photos'),
  ]);
  state.settings = {};
  for (const s of settings) state.settings[s.key] = s.value;
  state.journeys = journeys.sort((a, b) => (a.startDate < b.startDate ? -1 : 1));
  state.places = places.sort((a, b) => a.seq - b.seq);
  state.photos = photos;
  state.loaded = true;

  await migrateRoles();

  emit('data:changed');
}

/** 运行时迁移：为旧数据补齐 place.role（start/waypoint/destination） */
async function migrateRoles() {
  const missing = state.places.filter((p) => !p.role);
  if (!missing.length) return;
  const byJourney = new Map();
  for (const p of state.places) {
    if (!byJourney.has(p.journeyId)) byJourney.set(p.journeyId, []);
    byJourney.get(p.journeyId).push(p);
  }
  let changed = false;
  for (const list of byJourney.values()) {
    list.sort((a, b) => a.seq - b.seq);
    list.forEach((p, i) => {
      if (p.role) return;
      changed = true;
      if (list.length === 1) p.role = 'destination';
      else if (i === 0) p.role = 'start';
      else if (i === list.length - 1) p.role = 'destination';
      else p.role = 'waypoint';
    });
  }
  if (changed) await db.bulkPut('places', state.places);
}

export async function getSetting(key, def = null) {
  if (state.loaded) return state.settings[key] ?? def;
  const row = await db.get('settings', key);
  return row ? row.value : def;
}

export async function setSetting(key, value) {
  state.settings[key] = value;
  await db.put('settings', { key, value });
  // 设置变更不算数据变更，避免统计页无谓重渲染
  emit('settings:changed');
}

// ---- Journeys ----
export async function saveJourney(journey) {
  const now = new Date().toISOString();
  const rec = {
    ...journey,
    updatedAt: now,
    createdAt: journey.createdAt || now,
  };
  await db.put('journeys', rec);
  await reload();
  return rec;
}

export async function deleteJourney(id) {
  const places = state.places.filter((p) => p.journeyId === id);
  const photos = state.photos.filter((p) => p.journeyId === id);
  await db.del('journeys', id);
  await db.bulkDel('places', places.map((p) => p.id));
  await db.bulkDel('photos', photos.map((p) => p.id));
  await db.bulkDel('blobs', photos.map((p) => p.id));
  await reload();
}

export async function savePlaces(journeyId, places) {
  // 全量替换该 journey 的地点
  const old = state.places.filter((p) => p.journeyId === journeyId);
  await db.bulkDel('places', old.map((p) => p.id));
  const rows = places.map((p, i) => ({
    ...p,
    id: p.id || uuid(),
    journeyId,
    seq: i,
  }));
  await db.bulkPut('places', rows);
  await reload();
}

/** Read-only diagnostic for a journey's persisted record and ordered places. */
export async function debugJourneySave(id) {
  const [journey, allPlaces] = await Promise.all([
    db.get('journeys', id),
    db.getAll('places'),
  ]);
  const places = allPlaces
    .filter((p) => p.journeyId === id)
    .sort((a, b) => a.seq - b.seq);
  const result = {
    id,
    journey: journey || null,
    places,
    start: places.find((p) => p.role === 'start') || null,
    destination: places.find((p) => p.role === 'destination') || null,
    dates: {
      journeyStart: journey?.startDate || null,
      journeyEnd: journey?.endDate || null,
      placeDates: places.map(({ role, name, arriveAt }) => ({ role, name, arriveAt: arriveAt || null })),
    },
    coordinates: places.map(({ role, name, lat, lng }) => ({ role, name, lat: lat ?? null, lng: lng ?? null })),
  };
  console.info('[debugJourneySave]', result);
  return result;
}

// ---- Photos ----
export async function savePhoto({ journeyId, placeId, blob, mime }) {
  const id = uuid();
  // 生成缩略图（最长边 640）
  const thumb = await makeThumb(blob, 640);
  await db.put('photos', {
    id,
    journeyId,
    placeId,
    mime,
    width: 0,
    height: 0,
    createdAt: new Date().toISOString(),
  });
  await db.put('blobs', { id, blob: thumb });
  // 更新 place.photoIds
  const place = state.places.find((p) => p.id === placeId);
  if (place) {
    place.photoIds = [...(place.photoIds || []), id];
    await db.put('places', place);
  }
  await reload();
  return id;
}

export async function deletePhoto(id) {
  const photo = state.photos.find((p) => p.id === id);
  if (photo) {
    const place = state.places.find((p) => p.id === photo.placeId);
    if (place) {
      place.photoIds = (place.photoIds || []).filter((x) => x !== id);
      await db.put('places', place);
    }
  }
  await db.del('photos', id);
  await db.del('blobs', id);
  await reload();
}

export async function getPhotoBlob(id) {
  const rec = await db.get('blobs', id);
  return rec ? rec.blob : null;
}

export function getPhotoUrl(id) {
  // 懒加载：返回 Promise<objectURL>
  return getPhotoBlob(id).then((blob) => (blob ? URL.createObjectURL(blob) : null));
}

async function makeThumb(blob, max) {
  const url = URL.createObjectURL(blob);
  try {
    const img = await loadImage(url);
    const scale = Math.min(1, max / Math.max(img.width, img.height));
    if (scale >= 1 && blob.size < 200 * 1024) return blob;
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(img.width * scale);
    canvas.height = Math.round(img.height * scale);
    canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
    const out = await new Promise((res) =>
      canvas.toBlob(res, 'image/jpeg', 0.82)
    );
    return out || blob;
  } finally {
    URL.revokeObjectURL(url);
  }
}

function loadImage(url) {
  return new Promise((res, rej) => {
    const img = new Image();
    img.onload = () => res(img);
    img.onerror = rej;
    img.src = url;
  });
}

// ---- 派生选择器 ----
export function placesByJourney(journeyId) {
  return state.places
    .filter((p) => p.journeyId === journeyId)
    .sort((a, b) => a.seq - b.seq);
}

export function allPlacesChronological() {
  return [...state.places].sort((a, b) => {
    const da = a.arriveAt || a.visitedAt || '';
    const dbv = b.arriveAt || b.visitedAt || '';
    return da < dbv ? -1 : da > dbv ? 1 : a.seq - b.seq;
  });
}

export function uniquePlaces() {
  // 按名称+坐标去重，返回最近一次到访
  const map = new Map();
  for (const p of allPlacesChronological()) {
    const key = `${p.name}|${p.lat}|${p.lng}`;
    map.set(key, p);
  }
  return [...map.values()];
}

export function stats() {
  const journeys = state.journeys.length;
  const up = uniquePlaces();
  const cities = up.length;
  const countries = new Set(up.map((p) => p.country).filter(Boolean)).size;
  let distance = 0;
  for (const j of state.journeys) {
    const ps = placesByJourney(j.id);
    for (let i = 1; i < ps.length; i++) {
      distance += haversine(ps[i - 1], ps[i]);
    }
  }
  return { journeys, cities, countries, distance: Math.round(distance) };
}

export function journeyStats(journeyId) {
  const ps = placesByJourney(journeyId);
  const photos = state.photos.filter((p) => p.journeyId === journeyId).length;
  let distance = 0;
  for (let i = 1; i < ps.length; i++) distance += haversine(ps[i - 1], ps[i]);
  return { places: ps.length, photos, distance: Math.round(distance) };
}

function haversine(a, b) {
  const R = 6371;
  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
  const dLng = ((b.lng - a.lng) * Math.PI) / 180;
  const la1 = (a.lat * Math.PI) / 180;
  const la2 = (b.lat * Math.PI) / 180;
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(la1) * Math.cos(la2) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

/** 两地点间的大圆距离（公里），供 Stats Highlights 等外部计算使用 */
export function distanceBetween(a, b) {
  if (a.lat == null || a.lng == null || b.lat == null || b.lng == null) return 0;
  return haversine(a, b);
}

async function reload() {
  await loadAll();
}

